import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * What a set of insured items costs together, before any policy-wide modifier.
 *
 * Items are charged at their listed base premium, except that a building block of
 * exactly three alike components is offered at the special block premium.
 */
public class PolicyBasePremium {

    private static final int BLOCK_SIZE = 3;
    private static final int BLOCK_BASE_PREMIUM = 60;

    private final PriceList priceList = new PriceList();

    public double forItems(List<Item> items) {
        double total = 0;
        for (Map.Entry<String, List<Item>> alikeItems : groupByType(items).entrySet()) {
            total += basePremiumForAlike(alikeItems.getValue());
        }
        return total;
    }

    private Map<String, List<Item>> groupByType(List<Item> items) {
        Map<String, List<Item>> byType = new LinkedHashMap<>();
        for (Item item : items) {
            byType.computeIfAbsent(item.type(), type -> new java.util.ArrayList<>()).add(item);
        }
        return byType;
