/**
 * The risk surcharges the office adds for a single insured item.
 *
 * A cursed item and a highly enchanted item each carry a risk surcharge on that item's
 * own base premium, not on the premium of the whole policy. An item that is both carries
 * both surcharges.
 */
public class ItemRiskSurcharge {

    private static final double CURSE_SURCHARGE_RATE = 0.50;
    private static final double HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.30;
    private static final int HIGH_ENCHANTMENT_LEVEL = 5;

    private final PriceList priceList = new PriceList();

    public double forItem(Item item) {
        double basePremium = priceList.basePremiumFor(item);
        double surcharge = 0;
        if (item.cursed()) {
            surcharge += basePremium * CURSE_SURCHARGE_RATE;
        }
        if (isHighlyEnchanted(item)) {
            surcharge += basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE;
        }
        return surcharge;
    }

    private boolean isHighlyEnchanted(Item item) {
        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    }
}
