/**
 * The policy-wide modifiers the office applies to a quote, as one signed adjustment.
 *
 * Unlike a risk surcharge, which attaches to the one item that carries the risk, a
 * policy-wide modifier is assessed against the policy base premium -- the sum of all
 * item base premiums. Surcharges raise the adjustment, discounts lower it, and the
 * policy carries their sum.
 *
 * Only the initial assessment surcharge is recognised so far: every quote is a first
 * insurance of its items, so the office charges it on each one, whatever the customer's
 * history. The loyalty discount and the follow-up contract discount join it here once
 * the office can see the customer and the customer's earlier contracts.
 */
public class PolicyModifiers {

    private static final double INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.10;

    public double forPolicy(double policyBasePremium) {
        return initialAssessmentSurcharge(policyBasePremium);
    }

    private double initialAssessmentSurcharge(double policyBasePremium) {
        return policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
    }
}
import java.util.List;

/**
 * Computes the premium for a quote, in the order the office assesses it.
 *
 * The policy base premium from the MHPCO price list comes first. The item-specific risk
 * surcharges are then added on top of it, while the policy-wide modifiers are assessed
 * against the base premium itself rather than against the surcharged amount. The
 * processing fee is added at the very end, and only the final premium is rounded.
 */
public class PremiumCalculator {

    private static final int PROCESSING_FEE = 5;

    private final PolicyBasePremium policyBasePremiumRule = new PolicyBasePremium();
    private final PolicyRiskSurcharges policyRiskSurcharges = new PolicyRiskSurcharges();
    private final PolicyModifiers policyModifiers = new PolicyModifiers();

    public int premiumFor(QuoteStep quoteStep) {
        List<Item> items = quoteStep.items();
        double policyBasePremium = policyBasePremiumRule.forItems(items);
        double assessedPremium = policyBasePremium
                + policyRiskSurcharges.forItems(items)
                + policyModifiers.forPolicy(policyBasePremium);
        return roundInOfficesFavour(assessedPremium + PROCESSING_FEE);
    }

    private int roundInOfficesFavour(double premium) {
        return (int) Math.ceil(premium);
    }
}
import java.util.ArrayList;
import java.util.List;

public class ClaimOffice {

    private final PremiumCalculator premiumCalculator = new PremiumCalculator();

    public List<StepResult> run(Scenario scenario) {
        List<StepResult> results = new ArrayList<>();
        for (Step step : scenario.steps()) {
            QuoteStep quoteStep = (QuoteStep) step;
            results.add(new QuoteResult(premiumCalculator.premiumFor(quoteStep)));
        }
        return results;
    }
}

