import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: the base premium the office charges for a single insured item.
 *
 * The office prices two kinds of item differently. Each main item carries its own listed
 * base premium. Components -- runes, moonstones -- are all priced at one uniform component
 * rate, so a new component type joins the list without a price of its own.
 *
 * The list is also the office's statement of what it insures: a type the list does not
 * name is a type the office does not cover, and asking its price is met with an objection.
 * Membership and price are one fact per type, which is why they are kept together here --
 * taking on a new line of business is a single new entry.
 */
public class PriceList {

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private static final int COMPONENT_BASE_PREMIUM = 25;

    public boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }

    public int basePremiumFor(Item item) {
        if (isComponent(item)) {
            return COMPONENT_BASE_PREMIUM;
        }
        if (!isMainItem(item)) {
            throw new ClaimOfficeException("The office does not insure items of type " + item.type());
        }
        return MAIN_ITEM_BASE_PREMIUMS.get(item.type());
    }

    private boolean isMainItem(Item item) {
        return MAIN_ITEM_BASE_PREMIUMS.containsKey(item.type());
    }
}
import java.util.List;

/**
 * The items a policy covers, asked which of them a reported damage concerns.
 *
 * A damage report names only a type, so the office has to look the damaged item up among
 * the items the policy insures before any clause can be applied to it. That lookup is the
 * policy's knowledge of its own cover, not part of working out an amount, and it is where
 * the office's objections to a damage report outside the cover belong.
 */
public class InsuredItems {

    private final List<Item> items;

    public InsuredItems(List<Item> items) {
        this.items = items;
    }

    public Item coveringItemFor(Damage damage) {
        for (Item item : items) {
            if (item.type().equals(damage.itemType())) {
                return item;
            }
        }
        throw new ClaimOfficeException("The policy does not cover an item of type " + damage.itemType());
    }
}

