import java.util.ArrayList;
import java.util.List;

/**
 * Works through a scenario's steps in the order the office received them.
 *
 * The office keeps count of the customer's earlier contracts as it goes, because a quote is
 * assessed against the history that stands before it. Only a quote creates a contract; a claim
 * is made against a policy that already exists and so leaves that history untouched.
 */
public class ClaimOffice {

    private final PremiumCalculator premiumCalculator = new PremiumCalculator();
    private final PayoutCalculator payoutCalculator = new PayoutCalculator();

    public List<StepResult> run(Scenario scenario) {
        List<StepResult> results = new ArrayList<>();
        int earlierContracts = 0;
        for (Step step : scenario.steps()) {
            if (step instanceof QuoteStep quoteStep) {
                results.add(quote(quoteStep, scenario.customer(), earlierContracts));
                earlierContracts++;
            } else {
                ClaimStep claimStep = (ClaimStep) step;
                results.add(settle(claimStep.incident(), policyClaimedAgainst(claimStep, scenario)));
            }
        }
        return results;
    }

    private QuoteResult quote(QuoteStep quoteStep, Customer customer, int earlierContracts) {
        QuoteAssessment assessment = new QuoteAssessment(customer, earlierContracts);
        return new QuoteResult(premiumCalculator.premiumFor(quoteStep, assessment));
    }

    /**
     * Settling an incident against a policy: what the office pays for the damages reported,
     * and what that settlement leaves of the cap the policy was underwritten with.
     */
    private ClaimResult settle(Incident incident, InsuredItems insuredItems) {
        int payout = payoutCalculator.payoutFor(incident, insuredItems);
        return new ClaimResult(payout, insuredItems.cover().remainingCapAfter(payout));
    }

    /**
     * The policy a claim names: a claim carries the index of the quote step that created the
     * cover it is made against, so the office looks that step up to know what it insured.
     */
    private InsuredItems policyClaimedAgainst(ClaimStep claimStep, Scenario scenario) {
        return new InsuredItems(((QuoteStep) scenario.steps().get(claimStep.policy())).items());
    }
}
import java.util.List;

/**
 * What a policy is worth to the office: the insurance sum it has underwritten, and the
 * cap on everything it will ever pay out on that policy.
 *
 * The insurance sum is the plain sum of the listed insurance values of the covered items.
 * It is deliberately taken from the price list rather than from the premium: a block
 * discount lowers what the customer pays without lowering what the office insures, and a
 * risk surcharge raises the premium without raising the cap.
 */
public class PolicyCover {

    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

    private final int insuranceSum;

    private PolicyCover(int insuranceSum) {
        this.insuranceSum = insuranceSum;
    }

    public static PolicyCover of(List<Item> items) {
        PriceList priceList = new PriceList();
        int sum = 0;
        for (Item item : items) {
            sum += priceList.insuranceValueOf(item);
        }
        return new PolicyCover(sum);
    }

    /**
     * What the office will still pay out on this policy once a claim of this size has been
     * settled against it. The ceiling the office underwrote is twice the insurance sum, and
     * a settled claim consumes it.
     */
    public int remainingCapAfter(int payout) {
        return cap() - payout;
    }

    private int cap() {
        return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum;
    }
}

